def write(p,s): (ROOT/p).write_text(s,encoding='utf-8',newline='\n')
def sub(s,old,new):
    assert old in s, old[:90]
    return s.replace(old,new,1)
def line(s,needle,new):
    matches=[x for x in s.splitlines() if needle in x];assert len(matches)==1,(needle,len(matches))
    return sub(s,matches[0],new)

